-- CBRD-26659 Ticket03: exact serialized chunk-boundary neighbors and distinguishable bytes.
-- At16KiB: DB page16344, slotted header32, slot4, alignment8, OOS header24.
-- Max chunk payload=ALIGN_DOWN(16344-32-4,8)-24=16280.
-- For N>=32 byte VARBIT: L=ALIGN_UP(N+5,4), chunks=CEIL(L/16280).
-- Logical checks only. The private companion independently observes each fresh physical heap.
-- Each row has unique patterns and independently computed hex-text MD5.
-- Two boundaries retain below/exact/above controls. No redundant bulk levels.
-- Copy and UPDATE preserve complete values and row identities. Default JDBC autocommit.

drop table if exists t03_chunk_copy;
drop table if exists t03_chunk_source;
create table t03_chunk_source (id int primary key, payload bit varying);
create table t03_chunk_copy (id int primary key, payload bit varying);
insert into t03_chunk_source values
  (1,cast(concat(repeat('03',16271),repeat('04',0),repeat('05',0)) as bit varying)),
  (2,cast(concat(repeat('06',16275),repeat('07',0),repeat('08',0)) as bit varying)),
  (3,cast(concat(repeat('09',16275),repeat('0a',1),repeat('0b',0)) as bit varying)),
  (4,cast(concat(repeat('0c',16275),repeat('0d',16276),repeat('0e',0)) as bit varying)),
  (5,cast(concat(repeat('0f',16275),repeat('10',16280),repeat('11',0)) as bit varying)),
  (6,cast(concat(repeat('12',16275),repeat('13',16280),repeat('14',1)) as bit varying)),
  (7,cast(concat(repeat('15',16275),repeat('16',16280),repeat('17',17448)) as bit varying));
select id, octet_length(payload) as payload_octets, disk_size(payload) as payload_disk, md5(payload) as payload_md5, case when id=1 and payload=cast(concat(repeat('03',16271),repeat('04',0),repeat('05',0)) as bit varying) then 1 when id=2 and payload=cast(concat(repeat('06',16275),repeat('07',0),repeat('08',0)) as bit varying) then 1 when id=3 and payload=cast(concat(repeat('09',16275),repeat('0a',1),repeat('0b',0)) as bit varying) then 1 when id=4 and payload=cast(concat(repeat('0c',16275),repeat('0d',16276),repeat('0e',0)) as bit varying) then 1 when id=5 and payload=cast(concat(repeat('0f',16275),repeat('10',16280),repeat('11',0)) as bit varying) then 1 when id=6 and payload=cast(concat(repeat('12',16275),repeat('13',16280),repeat('14',1)) as bit varying) then 1 when id=7 and payload=cast(concat(repeat('15',16275),repeat('16',16280),repeat('17',17448)) as bit varying) then 1 else 0 end as value_ok from t03_chunk_source order by id;
insert into t03_chunk_copy select id,payload from t03_chunk_source;
select id, octet_length(payload) as payload_octets, disk_size(payload) as payload_disk, md5(payload) as payload_md5, case when id=1 and payload=cast(concat(repeat('03',16271),repeat('04',0),repeat('05',0)) as bit varying) then 1 when id=2 and payload=cast(concat(repeat('06',16275),repeat('07',0),repeat('08',0)) as bit varying) then 1 when id=3 and payload=cast(concat(repeat('09',16275),repeat('0a',1),repeat('0b',0)) as bit varying) then 1 when id=4 and payload=cast(concat(repeat('0c',16275),repeat('0d',16276),repeat('0e',0)) as bit varying) then 1 when id=5 and payload=cast(concat(repeat('0f',16275),repeat('10',16280),repeat('11',0)) as bit varying) then 1 when id=6 and payload=cast(concat(repeat('12',16275),repeat('13',16280),repeat('14',1)) as bit varying) then 1 when id=7 and payload=cast(concat(repeat('15',16275),repeat('16',16280),repeat('17',17448)) as bit varying) then 1 else 0 end as value_ok from t03_chunk_copy order by id;
update t03_chunk_copy set payload=cast(concat(repeat('fa',16275),repeat('fb',16280),repeat('fc',17452)) as bit varying) where id=7;
